import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        perm = []
        left = 1
        right = N

        for i in range(N):
            if i % 2 == 0:
                perm.append(right)
                right -= 1
            else:
                perm.append(left)
                left += 1

        results.append(" ".join(map(str, perm)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
